post:
  description: Creates a new dashboard and returns its ID, full state, and metadata.
  operationId: post-dashboards
  parameters:
    - description: A required header to protect against CSRF attacks
      in: header
      name: kbn-xsrf
      required: true
      schema:
        example: 'true'
        type: string
  requestBody:
    content:
      application/json:
        schema:
          $ref: '#/components/schemas/Kibana_HTTP_APIs_kbn-dashboard-data'
  responses:
    '201':
      content:
        application/json:
          examples:
            createDashboardResponse:
              description: |
                Response to creating a dashboard. Returns the generated ID, the full dashboard state in `data`, and metadata. Default option values are always returned even when not explicitly set in the request. Panel `id` values are generated automatically.
              summary: Create dashboard response
              value:
                data:
                  access_control:
                    access_mode: write_restricted
                  options:
                    auto_apply_filters: true
                    hide_panel_borders: false
                    hide_panel_titles: false
                    sync_colors: false
                    sync_cursor: true
                    sync_tooltips: false
                    use_margins: true
                  }
                ]
              }
            },
            {
              "grid": {
                "x": 36,
                "y": 0,
                "w": 12,
                "h": 5
              },
              "type": "vis",
              "config": {
                "type": "metric",
                "data_source": {
                  "type": "data_view_spec",
                  "index_pattern": "kibana_sample_data_logs",
                  "time_field": "timestamp"
                },
                "metrics": [
                  {
                    "type": "primary",
                    "operation": "average",
                    "field": "bytes"
                  }
                ]
              }
            },
            {
              "grid": {
                "x": 24,
                "y": 5,
                "w": 24,
                "h": 10
              },
              "type": "vis",
              "config": {
                "type": "xy",
                "title": "Requests over time",
                "layers": [
                  {
                    "type": "line",
                    "data_source": {
                      "type": "esql",
                      "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                    },
                    "x": {
                      "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
                    },
                    "y": [
                      {
                        "column": "count"
                      }
                    ]
                  }
                ],
                "axis": {
                  "x": {
                    "title": {
                      "visible": false
                    }
                  }
                }
              }
            }
          ]
        }'
    - label: Create a dashboard (simple) - Console
      lang: Console_simple
      source: |
        POST kbn:/api/dashboards
        {
          "title": "Web logs overview",
          "panels": [
            {
              "grid": {
                "x": 0,
                "y": 0,
                "w": 24,
                "h": 15
              },
              "type": "markdown",
              "config": {
                "content": "## Web logs overview\n\n&nbsp;\n\nCreated with the [Dashboards API](https://www.elastic.co/docs/api/doc/kibana) using the Kibana sample web logs dataset (`kibana_sample_data_logs`). Contains:\n- This markdown panel\n- 2 metrics, showing request count and average response size\n- A line chart based on an ES|QL query\n\n&nbsp;\n\n&nbsp;\n\n[Learn more about dashboards](https://www.elastic.co/docs/explore-analyze/dashboards)"
              }
            },
            {
              "grid": {
                "x": 24,
                "y": 0,
                "w": 12,
                "h": 5
              },
              "type": "vis",
              "config": {
                "type": "metric",
                "data_source": {
                  "type": "data_view_spec",
                  "index_pattern": "kibana_sample_data_logs",
                  "time_field": "timestamp"
                },
                "metrics": [
                  {
                    "type": "primary",
